// Map shapes, loaded separately from the main script.
//
// The polygon files here are generated by scripts/build_map_shapes.mjs from
// the full-precision sources (data/final_updated_regions.js and
// data/neighborhoods_geojson.js). They are imported on demand so the page
// can paint before 1 MB of coordinates has downloaded: tract shapes as soon
// as the map mounts, neighborhood shapes the first time that view is used.
// Each loader resolves to a GeoJSON FeatureCollection and is fetched once.

let tracts;
let neighborhoods;
let areas;

/** Census-tract polygons. Feature properties: { region_id }. */
export function loadTractShapes() {
  tracts ||= import("./tracts.min.json").then((m) => m.default);
  return tracts;
}

/** Neighborhood polygons. Feature properties: { neighborhood_id, neighborhood_name }. */
export function loadNeighborhoodShapes() {
  neighborhoods ||= import("./neighborhoods.min.json").then((m) => m.default);
  return neighborhoods;
}

/**
 * City of Austin planning areas for the area-name labels (built by
 * scripts/build_area_names.mjs). Feature properties: { id, name, level,
 * kind, lat, lng, km2, tracts, parent, children, top, hood, note }.
 */
export function loadAreaShapes() {
  areas ||= import("./areas.min.json").then((m) => m.default);
  return areas;
}
